if(!snapshot.length)return false;
const previous=[...(isFunction(grid.#source.data)?grid.#source.data():[])]
.filter((row)=>row!==undefined);
grid.rows.load(snapshot);
grid.#diff.setSnapshot(previous);
grid.#diffSwapped=!grid.#diffSwapped;
grid.#bus.emit('diff:swapped',{
swapped:grid.#diffSwapped,
rows:snapshot.length,
snapshot:previous.length,
},'api');
