if(this.#removedCache&&this.#removedCache.version===version)return this.#removedCache.rows;
const rows=this.#diff.removedRows().map((entry)=>createRow({
key:entry.key,
data:entry.data,
removed:true,
}));
for(const row of rows)row.removed=true;
this.#removedCache={version,rows};
